package funcs

import (
	"bytes"
	"strings"
	"text/template"
)

// The FUNCS.md generator is itself a text/template: the tool eats its own
// cooking.
var mdTmpl = template.Must(template.New("funcs.md").Funcs(template.FuncMap{
	"cell": func(s string) string { return strings.ReplaceAll(s, "|", `\|`) },
	"safe": func(name string) string {
		for _, u := range Unsafe {
			if u == name {
				return "no"
			}
		}
		return "yes"
	},
}).Parse(`# Template functions

<!-- Generated by ` + "`go generate ./internal/funcs`" + ` from internal/funcs/doc.go. Do not edit. -->

tmplforge adds {{len .Docs}} functions to the text/template builtins
(and, or, not, len, index, slice, printf, eq, lt, ...). Functions take
their subject argument last so they compose in pipelines:
` + "`{{.Pipeline}}`" + `.

` + "`funcs.Safe()`" + ` (used by ` + "`render -sandbox`" + ` and the web GUI) is
` + "`funcs.All()`" + ` minus the functions marked "no" in the Safe column.

| Function | Signature | Safe | Description | Example | Result |
|---|---|---|---|---|---|
{{- range .Docs}}
| ` + "`{{.Name}}`" + ` | ` + "`{{cell .Sig}}`" + ` | {{safe .Name}} | {{cell .Desc}} | ` + "`{{cell .Example}}`" + ` | ` + "`{{cell .Result}}`" + ` |
{{- end}}
`))

// Markdown renders the Docs table as docs/FUNCS.md.
func Markdown() ([]byte, error) {
	var b bytes.Buffer
	err := mdTmpl.Execute(&b, map[string]any{"Docs": Docs, "Pipeline": `{{ .name | default "world" | upper }}`})
	return b.Bytes(), err
}
